export const littleCloserId = (number: StoryLessonNumber) => `conversational-skills-L4-C3-${number}-${littleCloserEpisodes[number].skill}-ja-v1`;
export function buildLittleCloserLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: littleCloserEpisodes[number], id: littleCloserId(number), chapterName: 'A Little Closer',
    setting: 'Kamo House cafe, a fictional restaurant near the river, Gion and the Kamo River in Kyoto; a fictional Osaka design agency. Fukuoka is a future trip idea, not an arranged destination.',
    previousSummary: index === 0 ? 'Leo chose to stay in Kyoto and declined Bristol. The first market succeeded; Emma sent congratulations from Osaka. Leo and Nao accepted a dinner date for the following Saturday at six, with restaurant details to confirm. Emma and Leo remain separated.' : littleCloserEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: 'Adapted from the supplied A Little Closer outline (Level 4 Chapter 3): first dinner date, Emma/Ren mutual fresh start, unexpected Gion meeting, awkward group coffee, honest Nao/Leo conversation, second market invitation, Emma/Nao friendship repair, successful market/monthly announcement. Episodes map1-4/6-9;5/10 remain personalized checkpoints. Fixed speaking/listening/reading/speaking then speaking/speaking/reading/speaking. FirstdateSaturday6, Leoarrives5:45, restaurantconfirmed; followingweek Emma/Ren mutually revisit their earlier professional-only relationship after rebuilding trust, without undoing the Leo breakup or restoring the removed physical incident. FollowingSaturday2 Giondate then encounter;4:05-4:25coffee with all agreeing. Nao/Leo honest conversation afterward. Nextweek newmarketinvite; Friday2-4setup, Renpossible thenconfirmed, sixphotos; Saturdaymarket10-1 and Emma11:30frontwindowtalk. CaptionBristol->Kyoto. Monthlymarkets decided only after success, nextdatepending. Fukuokatrip remains a hope: check days off nextweek, no tickets/dates/move. Keep romance light, no physical-intimacy scenes, no forced reconciliation or instant erasure of the past. Short supported B1-B2, direct roles, no alternate-character/personal-information disclaimers, no compulsory monologues. Japanese support, basic pronunciation, standard guides/fixed rubric and observed-error tracking. No images. Level 4 Chapters 4-5 await user outlines.',
  });
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'Designer rebuilding confidence and friendship. After time and professional boundaries, mutually chooses to date Ren honestly. Shares photos at the second market, without resuming her relationship with Leo.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'Baker staying in Kyoto. Begins dating Nao, acknowledges mixed feelings honestly and exchanges peaceful goodwill with Emma.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'Ceramic artist and photographer dating Leo. Asks direct questions, reconnects with Emma as a friend and suggests a future Fukuoka visit.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Kamo House organiser. Invites contributions and setup help, enjoys the group\'s surprising news and announces monthly markets after the second success.' },
    { id: 'ren', name: 'Ren', role: 'supporting', description: 'Design coworker who agrees to honest dating with Emma while keeping team work decisions professional. Helps carry frames and works amicably with Leo.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 4, chapter: 3, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 3: A Little Closer', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja' };
}
export function buildLittleCloserChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildLittleCloserLesson(number, {}, reference));
}
